        }

        print("\n📈 系统状态:")
        for k, v in status.items():
            print(f"  {k}: {v}")
        print()

    def list_models(self):
        """列出所有模型"""
        if not self.system.model_registry:
            print("🤷 没有已训练的模型")
            return

        print(f"\n🤖 已注册模型 ({len(self.system.model_registry)}个):")
