class ModelOptimizer:
    def __init__(self, model):
        self.model = model

    def quantize_dynamic(self):
        import torch.quantization
        return torch.quantization.quantize_dynamic(
            self.model, {torch.nn.Linear, torch.nn.Conv2d}, dtype=torch.qint8
        )

    def prune_l1(self, amount=0.3):
        import torch.nn.utils.prune as prune
        parameters_to_prune = []
        for name, module in self.model.named_modules():
            if isinstance(module, (torch.nn.Linear, torch.nn.Conv2d)):
                parameters_to_prune.append((module, 'weight'))
        prune.global_unstructured(parameters_to_prune, pruning_method=prune.L1Unstructured, amount=amount)
        return self.model

    def export_onnx(self, dummy_input, output_path):
        torch.onnx.export(self.model, dummy_input, output_path,
                          opset_version=13, input_names=['input'], output_names=['output'],
                          dynamic_axes={'input': {0: 'batch_size'}, 'output': {0: 'batch_size'}})

import os
import pandas as pd
from glob import glob

def load_data_from_folder(folder_path, file_pattern="*.csv"):
    """
    自动化获取文件夹中的本地存储数据

    参数:
        folder_path: 数据文件夹路径
        file_pattern: 文件匹配模式(如"*.csv", "*.xlsx")

    返回:
        合并后的DataFrame
    """
    # 获取所有匹配的文件
    file_paths = glob(os.path.join(folder_path, file_pattern))

    # 读取并合并所有文件
    dfs = []
    for file_path in file_paths:
        try:
            if file_path.endswith('.csv'):
                df = pd.read_csv(file_path)
            elif file_path.endswith('.xlsx') or file_path.endswith('.xls'):
                df = pd.read_excel(file_path)
            else:
                continue
            dfs.append(df)
        except Exception as e:
            print(f"Error reading {file_path}: {str(e)}")

    if not dfs:
        raise ValueError("No valid data files found in the specified folder")

    return pd.concat(dfs, ignore_index=True)

from cryptography.fernet import Fernet
import base64

class SecurityManager:
    def __init__(self, key=None):
        self.key = key or Fernet.generate_key()
        self.cipher = Fernet(self.key)

    def encrypt_data(self, data: bytes) -> bytes:
        return self.cipher.encrypt(data)

    def decrypt_data(self, data: bytes) -> bytes:
        return self.cipher.decrypt(data)

    def encrypt_model_weights(self, model_path, out_path):
        with open(model_path, 'rb') as f:
            enc = self.encrypt_data(f.read())
        with open(out_path, 'wb') as f:
            f.write(enc)

