return "python"
elif any(word in text_lower for word in ['javascript', 'js', 'node', 'react']):
return "javascript"
elif any(word in text_lower for word in ['typescript', 'ts', 'type']):
return "typescript"
elif any(word in text_lower for word in ['java', 'spring', 'jvm']):
