#!/bin/bash
MIN_COVERAGE=80
COVERAGE_FILE="coverage/coverage-summary.json"

if [ -f "$COVERAGE_FILE" ]; then
    COVERAGE=$(node -p "require('$COVERAGE_FILE').total.lines.pct")
    echo "当前覆盖率: $COVERAGE%"

    if (( $(echo "$COVERAGE < $MIN_COVERAGE" | bc -l) )); then
        echo "❌ 覆盖率低于 $MIN_COVERAGE%"
        exit 1
    else
        echo "✅ 覆盖率达标"
    fi
else
